/* global document, Office, console */

import { loadSettings, saveSettings, DEFAULT_SETTINGS, Settings } from "../shared/settings";
import { runChecks, CheckResult } from "../shared/checkEngine";

const BUILD_TAG = "v1.1.0-live-check-2026-06-09";

Office.onReady((info) => {
  console.log(`[PauseMan] taskpane onReady ${BUILD_TAG} host=${info.host}`);
  if (info.host === Office.HostType.Outlook) {
    populate(loadSettings());
    document.getElementById("save")!.addEventListener("click", onSave);
    const recheck = document.getElementById("recheck");
    if (recheck) recheck.addEventListener("click", runCheck);
    // コンポーズ中なら開いた瞬間に1回チェック
    runCheck();
    // 宛先が変わるたびに自動で再チェック(誤送信で最も危険な宛先を常時監視。要件セット 1.7+)
    try {
      const item: any = Office.context.mailbox.item;
      if (item && typeof item.addHandlerAsync === "function") {
        item.addHandlerAsync(Office.EventType.RecipientsChanged, () => runCheck());
        console.log(`[PauseMan] RecipientsChanged ハンドラ登録`);
      }
    } catch (e) {
      console.log(`[PauseMan] addHandler 失敗(無視可): ${e}`);
    }
  }
});

// ===== 送信前チェック =====

function getAsyncP<T>(fn: (cb: (r: Office.AsyncResult<T>) => void) => void): Promise<T> {
  return new Promise((resolve, reject) => {
    try {
      fn((r) => {
        if (r.status === Office.AsyncResultStatus.Succeeded) resolve(r.value);
        else reject(new Error(r.error?.message || "getAsync failed"));
      });
    } catch (e) {
      reject(e);
    }
  });
}

async function gatherMailData() {
  const item: any = Office.context.mailbox.item;
  if (!item || !item.to || typeof item.to.getAsync !== "function") {
    throw new Error("compose-context-unavailable");
  }
  const [to, cc, bcc, subject, body] = await Promise.all([
    getAsyncP<Office.EmailAddressDetails[]>((cb) => item.to.getAsync(cb)),
    getAsyncP<Office.EmailAddressDetails[]>((cb) => item.cc.getAsync(cb)),
    getAsyncP<Office.EmailAddressDetails[]>((cb) => item.bcc.getAsync(cb)),
    getAsyncP<string>((cb) => item.subject.getAsync(cb)),
    getAsyncP<string>((cb) => item.body.getAsync(Office.CoercionType.Text, cb)),
  ]);
  return { to: to || [], cc: cc || [], bcc: bcc || [], subject: subject || "", body: body || "" };
}

async function runCheck() {
  const out = document.getElementById("check-results");
  if (!out) return;
  out.innerHTML = `<div class="pm-checking">チェック中...</div>`;
  try {
    const data = await gatherMailData();
    const results = runChecks(data, loadSettings());
    renderResults(results);
  } catch (e: any) {
    const msg = e?.message === "compose-context-unavailable"
      ? "新規作成（コンポーズ）中のメールで開いてください。"
      : `読み取りに失敗しました: ${escapeHtml(e?.message ?? String(e))}`;
    out.innerHTML = `<div class="pm-result pm-info">${msg}</div>`;
  }
}

function renderResults(results: CheckResult[]) {
  const out = document.getElementById("check-results")!;
  if (results.length === 0) {
    out.innerHTML = `<div class="pm-result pm-ok"><strong>✅ 問題は見つかりませんでした</strong><div class="pm-detail">送信して大丈夫です。</div></div>`;
    return;
  }
  const errs = results.filter((r) => r.level === "error").length;
  const warns = results.filter((r) => r.level === "warning").length;
  const summary = errs
    ? `<div class="pm-summary pm-error">🚫 確認が必要な項目が ${errs} 件あります${warns ? `（注意 ${warns} 件）` : ""}</div>`
    : `<div class="pm-summary pm-warning">⚠️ 注意が ${warns} 件あります</div>`;
  const items = results
    .map((r) => {
      const cls = r.level === "error" ? "pm-error" : r.level === "warning" ? "pm-warning" : "pm-info";
      const icon = r.level === "error" ? "🚫" : r.level === "warning" ? "⚠️" : "ℹ️";
      return `<div class="pm-result ${cls}"><strong>${icon} ${escapeHtml(r.title)}</strong><div class="pm-detail">${escapeHtml(r.detail)}</div></div>`;
    })
    .join("");
  out.innerHTML = summary + items;
}

function escapeHtml(s: string): string {
  return String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c] as string));
}

// ===== 設定 =====

function populate(s: Settings) {
  (document.getElementById("chk-subject") as HTMLInputElement).checked = s.checkEmptySubject;
  (document.getElementById("chk-body") as HTMLInputElement).checked = s.checkEmptyBody;
  (document.getElementById("chk-external") as HTMLInputElement).checked = s.checkExternalDomain;
  (document.getElementById("chk-recipcount") as HTMLInputElement).checked = s.checkRecipientCount;
  (document.getElementById("recip-threshold") as HTMLInputElement).value = String(s.recipientCountThreshold);
  (document.getElementById("internal-domains") as HTMLTextAreaElement).value = s.internalDomains.join("\n");
  (document.getElementById("forbidden-words") as HTMLTextAreaElement).value = s.forbiddenWords.join("\n");
}

function readForm(): Settings {
  const lines = (id: string) =>
    (document.getElementById(id) as HTMLTextAreaElement).value
      .split(/\r?\n/)
      .map((s) => s.trim())
      .filter((s) => s.length > 0);

  return {
    checkEmptySubject: (document.getElementById("chk-subject") as HTMLInputElement).checked,
    checkEmptyBody: (document.getElementById("chk-body") as HTMLInputElement).checked,
    checkExternalDomain: (document.getElementById("chk-external") as HTMLInputElement).checked,
    checkRecipientCount: (document.getElementById("chk-recipcount") as HTMLInputElement).checked,
    recipientCountThreshold:
      parseInt((document.getElementById("recip-threshold") as HTMLInputElement).value, 10) ||
      DEFAULT_SETTINGS.recipientCountThreshold,
    internalDomains: lines("internal-domains"),
    forbiddenWords: lines("forbidden-words"),
  };
}

async function onSave() {
  const status = document.getElementById("status")!;
  status.textContent = "保存中...";
  status.className = "pm-status";
  try {
    await saveSettings(readForm());
    status.textContent = "✅ 保存しました";
    status.className = "pm-status pm-status-ok";
    // 設定変更を反映して再チェック
    runCheck();
    setTimeout(() => (status.textContent = ""), 2500);
  } catch (e: any) {
    status.textContent = `❌ 保存失敗: ${e?.message ?? e}`;
    status.className = "pm-status pm-status-err";
  }
}
